-- ID documents: identity card, passport, health card and driving licence, under
-- one ID_DOCUMENT type. Every template asks for the holder and the document
-- with the same keys (last_name, first_name, tax_code, birth_date, birth_place,
-- sex, citizenship, document_number, issuer, issue_date, expiry_date...), so the
-- data of all of them merges into one person. These keys mirror the person
-- fields of the life-island-docs blueprints (firstName, lastName, taxCode...).
-- An ID document always waits for review (reason PERSON_DATA).
-- The subtypes go below ID_DOCUMENT; if you already had a category titled
-- "ID document" (so ID_DOCUMENT is skipped) they stay top-level instead.
-- Data only; a category with the same id or title that you created already is
-- kept as it is. Rollback: drizzle/rollback/0010_id_document_categories.down.sql.
WITH inserted AS (
  INSERT INTO "ingestion"."document_categories" ("id", "title", "description", "template_json", "parent_id", "dimension") VALUES
  ('ID_DOCUMENT', 'ID document', 'An identity document of a person: identity card, passport, health card (tessera sanitaria / codice fiscale) or driving licence. Its holder data is checked against the person before it is kept.', '{"fields": [{"key": "last_name", "label": "Last name", "type": "string", "description": "Cognome / surname of the holder, as printed", "required": true}, {"key": "first_name", "label": "First name", "type": "string", "description": "Nome / given names of the holder, as printed", "required": true}, {"key": "tax_code", "label": "Tax code", "type": "string", "description": "Codice fiscale of the holder, if printed", "required": false, "pattern": "^[A-Z0-9]{16}$"}, {"key": "birth_date", "label": "Birth date", "type": "date", "description": "Data di nascita of the holder", "required": true}, {"key": "birth_place", "label": "Birth place", "type": "string", "description": "Luogo di nascita: town, with the province or country, as printed", "required": false}, {"key": "sex", "label": "Sex", "type": "enum", "description": "Sesso, as printed", "required": false, "options": ["M", "F", "X"]}, {"key": "citizenship", "label": "Citizenship", "type": "string", "description": "Cittadinanza / nationality as an ISO 3166-1 alpha-2 code, e.g. IT", "required": false}, {"key": "document_number", "label": "Document number", "type": "string", "description": "Number of the document as printed, without spaces", "required": true}, {"key": "issuer", "label": "Issued by", "type": "string", "description": "Office that issued it (Comune, Questura, MIT-UCO, Agenzia delle Entrate), as printed", "required": false}, {"key": "issuing_country", "label": "Issuing country", "type": "string", "description": "Country that issued it, ISO 3166-1 alpha-2, e.g. IT", "required": false}, {"key": "issue_date", "label": "Issue date", "type": "date", "description": "Data di rilascio / emissione", "required": false}, {"key": "expiry_date", "label": "Expiry date", "type": "date", "description": "Data di scadenza / valid until", "required": true}]}'::jsonb, NULL, 'DOCUMENT_TYPE')
  ON CONFLICT DO NOTHING
  RETURNING "id", "title", "parent_id", "dimension"
)
-- Modules that keep their own copy of the categories (review inbox, Home) learn them from category.changed@1.
INSERT INTO "ingestion"."outbox" (event_type, payload)
SELECT 'category.changed@1',
       jsonb_build_object(
         'id', i.id,
         'title', i.title,
         'parentId', i.parent_id,
         'dimension', i.dimension,
         'deleted', false,
         'changedAt', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
       )
  FROM inserted i;--> statement-breakpoint
