ress", "label": "Residence", "type": "string", "description": "Residenza / address of the holder, as printed (a passport prints only the town)", "required": false}, {"key": "height_cm", "label": "Height", "type": "integer", "description": "Statura of the holder", "required": false, "unit": "cm"}, {"key": "card_format", "label": "Card format", "type": "enum", "description": "Electronic card with chip (CIE) or paper booklet", "required": false, "options": ["electronic", "paper"]}, {"key": "card_access_number", "label": "Card access number", "type": "string", "description": "CAN: the 6 digits on the front of a CIE", "required": false, "pattern": "^[0-9]{6}$"}, {"key": "valid_for_travel", "label": "Valid for travel", "type": "boolean", "description": "False when printed ''non valida per l''espatrio''", "required": false}]}'::jsonb, 'DOCUMENT_TYPE'),
