pe": "string", "description": "Residenza / address of the holder, as printed (a passport prints only the town)", "required": false}, {"key": "height_cm", "label": "Height", "type": "integer", "description": "Statura of the holder", "required": false, "unit": "cm"}, {"key": "passport_type", "label": "Passport type", "type": "string", "description": "Tipo / type, usually P", "required": false}, {"key": "eye_color", "label": "Eye colour", "type": "enum", "description": "Colore degli occhi", "required": false, "options": ["brown", "blue", "green", "grey", "hazel", "black"]}]}'::jsonb, 'DOCUMENT_TYPE'),
