uired": true}, {"key": "card_kind", "label": "Card kind", "type": "enum", "description": "Tessera sanitaria or tesserino codice fiscale", "required": false, "options": ["health_insurance_card", "tax_code_card"]}, {"key": "institution_code", "label": "Institution code", "type": "string", "description": "EHIC field 7: identification number of the institution", "required": false}]}'::jsonb, 'DOCUMENT_TYPE'),
