nce_address", "label": "Residence", "type": "string", "description": "Residenza / address of the holder, as printed (a passport prints only the town)", "required": false}, {"key": "licence_categories", "label": "Categories", "type": "string", "description": "Categories held (field 9), comma separated, e.g. AM, B", "required": false}, {"key": "restriction_codes", "label": "Restriction codes", "type": "string", "description": "Field 12 codes, comma separated, e.g. 01.01", "required": false}]}'::jsonb, 'DOCUMENT_TYPE')
